class BnwPrimaryDefaultStageTrace final {
    const char* const label_;
    const long long ordinal_;
    std::chrono::steady_clock::time_point begin_{};
    int exceptions_=0;
 public:
    // Process diagnostic choice only; exact "1" enables the five LiveQuery labels.
    static bool detailed_live_query_enabled()noexcept {
        const DWORD saved_error=GetLastError();const int saved_errno=errno;
        static const bool enabled=[]()noexcept {
            wchar_t value[2]{};
            return GetEnvironmentVariableW(L"CIVIS_BNW_TRACE_LIVE_QUERY",value,2)==1&&value[0]==L'1';
        }();
        errno=saved_errno;SetLastError(saved_error);return enabled;
    }
    explicit BnwPrimaryDefaultStageTrace(const char* label,long long ordinal=-1)noexcept
        :label_(label),ordinal_(ordinal){
        const int saved_errno=errno;const DWORD saved_error=GetLastError();
        begin_=std::chrono::steady_clock::now();exceptions_=std::uncaught_exceptions();
        const auto stamp=std::chrono::duration_cast<std::chrono::milliseconds>(begin_.time_since_epoch()).count();
        if(ordinal_>=0)
            std::fprintf(stderr,"[BNW_STAGE] BEGIN %s ordinal=%lld steady_ms=%lld elapsed_ms=0\n",
                label_,ordinal_,static_cast<long long>(stamp));
        else
            std::fprintf(stderr,"[BNW_STAGE] BEGIN %s steady_ms=%lld elapsed_ms=0\n",
                label_,static_cast<long long>(stamp));
        std::fflush(stderr);SetLastError(saved_error);errno=saved_errno;
    }
    BnwPrimaryDefaultStageTrace(const BnwPrimaryDefaultStageTrace&)=delete;
    BnwPrimaryDefaultStageTrace& operator=(const BnwPrimaryDefaultStageTrace&)=delete;
    ~BnwPrimaryDefaultStageTrace()noexcept{
        const int saved_errno=errno;const DWORD saved_error=GetLastError();
        const auto now=std::chrono::steady_clock::now();
        const auto stamp=std::chrono::duration_cast<std::chrono::milliseconds>(now.time_since_epoch()).count();
        const auto elapsed=std::chrono::duration_cast<std::chrono::milliseconds>(now-begin_).count();
        const int unwind=std::uncaught_exceptions()>exceptions_?1:0;
        if(ordinal_>=0)
            std::fprintf(stderr,"[BNW_STAGE] END %s ordinal=%lld steady_ms=%lld elapsed_ms=%lld unwind=%d\n",
                label_,ordinal_,static_cast<long long>(stamp),static_cast<long long>(elapsed),unwind);
        else
            std::fprintf(stderr,"[BNW_STAGE] END %s steady_ms=%lld elapsed_ms=%lld unwind=%d\n",
                label_,static_cast<long long>(stamp),static_cast<long long>(elapsed),unwind);
        std::fflush(stderr);SetLastError(saved_error);errno=saved_errno;
    }
};
void need(bool value, const char* why) { if (!value) throw std::runtime_error(why); }
bool equal(const content::XmlNode& a, const content::XmlNode& b) {
    if (a.name != b.name || a.text != b.text || a.attributes != b.attributes ||
        a.children.size() != b.children.size()) return false;
    for (std::size_t n = 0; n < a.children.size(); ++n)
        if (!equal(a.children[n], b.children[n])) return false;
    return true;
}
struct Entry {
    std::filesystem::path relative;
    DWORD attributes;
    bool operator==(const Entry&) const = default;
};
std::vector<Entry> scan(const std::filesystem::path& root) {
    std::vector<Entry> out;
    const auto visit = [&](auto&& self, const std::filesystem::path& relative) -> void {
        const auto dir = root / relative;
        need(std::filesystem::is_directory(dir), "Native package Assets directory missing");
        // 821FE0 emits matching ordinary files, then recurses directories in
        // FindFirst/Next order. No sorting or save-selected inventory substitution.
        struct Find {
            HANDLE h = INVALID_HANDLE_VALUE;
            ~Find() { if (h != INVALID_HANDLE_VALUE) FindClose(h); }
        } files, dirs;
        WIN32_FIND_DATAW data{};
        files.h = native_fresh_find_detail::first((dir / L"*.civ5pkg").c_str(), &data);
        if (files.h != INVALID_HANDLE_VALUE) {
            do {
                const auto attrs = data.dwFileAttributes;
                if ((attrs & 0x16) != 0) continue;
                const std::filesystem::path name = data.cFileName;
                need((attrs & FILE_ATTRIBUTE_REPARSE_POINT) == 0,
                     "Native package reparse file requires target owner");
                out.push_back({relative / name, attrs});
            } while (FindNextFileW(files.h, &data));
            need(GetLastError() == ERROR_NO_MORE_FILES, "Native package file enumeration incomplete");
        } else {
            need(GetLastError() == ERROR_FILE_NOT_FOUND,
                 "Native package source file enumeration failed");
        }
        dirs.h = native_fresh_find_detail::first((dir / L"*").c_str(), &data);
        need(dirs.h != INVALID_HANDLE_VALUE, "Native package directory enumeration failed");
        do {
            if ((data.dwFileAttributes & 0x16) != 0x10) continue;
            const std::filesystem::path name = data.cFileName;
            if (name == L"." || name == L"..") continue;
            need((data.dwFileAttributes & FILE_ATTRIBUTE_REPARSE_POINT) == 0,
                 "Native package reparse traversal requires target owner");
            const auto path = relative / name;
            // The source callback can also receive matching package directories;
            // that descriptor semantics is not silently treated as a normal dir.
            need(runtime::ascii_lower(assets::path_utf8(name.extension())) != ".civ5pkg",
                 "Native matching package directory requires descriptor owner");
            out.push_back({path, data.dwFileAttributes});
            self(self, path);
        } while (FindNextFileW(dirs.h, &data));
        need(GetLastError() == ERROR_NO_MORE_FILES, "Native package directory enumeration incomplete");
    };
    visit(visit, {});
    return out;
}
