DWORD native_missing_open(const std::filesystem::path& path) {
    // Indexed loose820750/839FE0 reconstructs CP_ACP filename as UTF16,
    //828FB0/8202F0 ->829210 calls CreateFileW. Read1: share3/open3.
    const auto file = CreateFileW(path.c_str(), GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE,
                                  nullptr, OPEN_EXISTING, 0x08000080, nullptr);
    if (file != INVALID_HANDLE_VALUE) { CloseHandle(file); return ERROR_SUCCESS; }
    return GetLastError();
}
