assets::ResourceMountHit detail::NativeResourceRecordIndex::lookup(const assets::AssetKey& key) const {
        const auto found = records.find(source_hash(key.original_name()));
        if (found == records.end()) return {};
        if (const auto* unavailable = std::get_if<UnreadableLoose>(&found->second)) {
            need(native_missing_open(unavailable->native_path) == unavailable->error,
                 "Native indexed unreadable loose open result changed");
            throw std::runtime_error("Native indexed loose CP_ACP record cannot open reconstructed UTF16 payload: " +
                                     unavailable->relative);
        }
        return {std::get<assets::AssetHandle>(found->second), true};
    }

