    const detail::BnwNativePrimary32SourceBindings* retained_step(
        const detail::BnwNativePrimary32SourceBindings& issued) const {
        if (primary32_pending && primary32_pending->source_step_brand.get() == issued.source_step_brand.get())
            return primary32_pending.get();
        for (const auto& step : primary32_steps)
            if (step->source_step_brand.get() == issued.source_step_brand.get()) return step.get();
        return nullptr;
    }
    // Read sealed Primary32 links in their existing owner. Warm receives only
    // the matched archive witnesses; it gains no access to mutable bindings.
    void find_installed_color_primary_archive(std::uint32_t index,const assets::FpkSource* source,
        std::shared_ptr<const detail::BnwNativeGlobalArchivePrefixRecord>& prefix,
        std::shared_ptr<const detail::BnwNativeArchiveCachePublicationOwner>& publication)const {
        require_active_header_without_callbacks();
        need(installation_input&&live_resource_query&&!prefix&&!publication,
             "Installed Color primary lookup requires fresh actual installed operation");
        live_resource_query->require_installed_color_skin_identity();
        for(const auto& step:primary32_steps){
            if(!step->prefix||step->prefix->source_index()!=index)continue;
            need(!prefix,"Installed Color actual prefix aliases another archive attempt");
            prefix=step->prefix;publication=step->publication;
            need(step->header&&publication&&&prefix->header_owner()==step->header.get()&&
                 publication->canonical_payload_source().get()==source,
                 "Installed Color Default archive lost actual publication/Header");
        }
    }
