    detail::BnwNativePrimary32JournalFrameDiagnostic current_installation_completed_primary32_journal(
        const BnwNativePackageDiscoveryOwner& parent,const HeaderGuard& fence)const{
        // Each supported producer operand has its own live authentication;
        // every other/later phase retains the original ordinary FULL call.
        const auto record_phase=record_projection_journal_operand_without_callbacks();
        const bool initial=installation_input&&!lease&&!rules&&installation_first_archive_returned&&
             installation_primary32_attempted&&primary32_attempted&&primary32_claimed&&
             primary32_source_completed==32&&primary32_steps.size()==32&&!primary32_pending&&
             !installation_record_projection_attempted&&!record_snapshot_attempted&&!default_projection_attempted&&
             !production_default_attempted&&!production_default_published&&!frame.primary_dx9_registration_complete&&
             !installation_boot_attempted&&!common_driver_attempted&&!common_pending&&!installed_default_common&&!live_resource_query;
        if(!initial&&record_phase==0)return primary32_journal->current();
        const auto* const journal=primary32_journal.get();const auto& input=*installation_input;
        const auto* const projection=default_projection_pending?default_projection_pending.get():prepared_default_projection.get();
        const auto controller=+[](const BnwNativePackageDiscoveryOwner& actual,const HeaderGuard& actual_fence,
                                  const BnwNativeInstallationInputOwner& source){
            const auto& i=*actual.impl_;
            i.require_active_header_without_callbacks();
            const auto phase=i.record_projection_journal_operand_without_callbacks();
            if(phase!=0){
                need(i.active_header_fence==&actual_fence&&i.installation_input.get()==&source&&!i.category_lineage_failed,
                     "Retained record/projection Journal lost actual source/fence");
                if(phase==1){
                    // The real capture check precedes brand/bindings issuance.
                    need((i.self.use_count()-static_cast<long>(i.directory_parent_internal_pin_count()))>1&&!i.record_snapshot_failed,
                         "Native snapshot capture lost outside Package");
                    need(!i.primary32_failed,"Native snapshot capture incomplete/replayed source");
                    for(const auto& step:i.primary32_steps){
                        need(bool(step),"Primary32 completion source binding absent");i.require_exact_step_without_callbacks(*step);
                    }
                }else{
                    need(!i.record_snapshot_failed,"Installed real record snapshot/Default projection source lost");
                    const auto* operand=i.default_projection_pending?i.default_projection_pending.get():i.prepared_default_projection.get();
                    actual.require_default_projection_operation_current(*operand->source,operand->records);
                }
                return;
            }
            need(i.installation_input.get()==&source&&!i.lease&&!i.rules&&i.primary32_journal&&
                 i.installation_first_archive_returned&&i.installation_primary32_attempted&&!i.category_lineage_failed&&
                 !i.installation_record_projection_attempted&&!i.production_default_attempted&&!i.installation_boot_attempted&&
                 !i.common_driver_attempted&&!i.common_pending&&!i.installed_default_common&&!i.live_resource_query,
                 "Retained completed32 pass lost actual installed source/phase");
            actual.require_primary32_completion_observation_current(*i.primary32_journal,actual_fence);
            // During Journal.validate its existing parent.lock is accounted by
            // the unchanged retained-step (>2) check after EVERY FULL supplier.
        };
        const auto check=[&]{
            controller(parent,fence,input);
            need(parent.impl_.get()==this&&primary32_journal.get()==journal&&installation_has_outside_parent(),
                 "Retained completed32 pass lost canonical Journal/outside Parent");
            if(record_phase!=0)need(record_projection_journal_operand_without_callbacks()==record_phase&&
                 (default_projection_pending?default_projection_pending.get():prepared_default_projection.get())==projection,
                 "Retained record/projection Journal changed actual producer operand");
        };
        check();input.require_current();check(); // Strict PRE, before borrowing.
        const auto actual=[&]{
            BnwNativeInstallationInputOwner::RetainedPrimary32Validation retained(input,parent,fence,controller);
            struct Observation final{
                const BnwNativePackageDiscoveryOwner* previous_completed;
                const BnwNativePackageDiscoveryOwner* previous_record;
                const unsigned previous_phase;
                Observation(const BnwNativePackageDiscoveryOwner& value,unsigned phase)noexcept:
                    previous_completed(primary32_completed_pass_observer),previous_record(record_projection_journal_observer),
                    previous_phase(record_projection_journal_observer_phase){
                    if(phase==0)primary32_completed_pass_observer=&value;
                    else{record_projection_journal_observer=&value;record_projection_journal_observer_phase=phase;}
                }
                ~Observation()noexcept{
                    primary32_completed_pass_observer=previous_completed;record_projection_journal_observer=previous_record;
                    record_projection_journal_observer_phase=previous_phase;
                }
            } observation(parent,record_phase); // These tags never select authority.
            BnwPrimaryDefaultStageTrace trace(record_phase?"primary_default.record_projection.journal":"primary_default.primary32.completed_journal",
                record_phase?static_cast<long long>(record_phase):-1);
            const auto result=journal->current(); // ONE unchanged ordinary full32 pass.
            check();retained.require_current();check();return result;
        }(); // Tag clears BEFORE borrower cleanup on normal/unwind.
        input.require_current();check(); // Strict POST before frame leaves this actual pass.
        return actual;
    }
