void BnwNativePackageDiscoveryOwner::require_default_projection_operation_current(
    const detail::BnwNativePrimary32RecordSourceBindings& b,
    const detail::NativeResourceRecordIndex& records)const {
    const auto& i=*impl_;i.require_active_header_without_callbacks();
    const auto* actual=i.default_projection_pending?i.default_projection_pending.get():i.prepared_default_projection.get();
    // This member receives no Package weak-lock pin: exactly the active Root
    // guard plus a real outside facade must survive every callback.
    need((i.self.use_count()-static_cast<long>(i.directory_parent_internal_pin_count()))>1 && i.default_projection_attempted && !i.default_projection_failed &&
         actual && actual->source.get()==&b && &actual->records==&records && i.default_projection_brand &&
         b.actual_snapshot_brand.get()==i.default_projection_brand.get() &&
         !b.package.owner_before(i.self) && !i.self.owner_before(b.package) &&
         b.lease.get()==i.lease.get() && b.installation_input.get()==i.installation_input.get() &&
         (static_cast<bool>(b.lease)!=static_cast<bool>(b.installation_input)) && b.cold.get()==i.cold.get() && b.prefixes.get()==i.prefixes.get() &&
         b.arena.get()==i.entry_arena.get() && b.cache.get()==i.archive_cache.get() &&
         b.journal.get()==i.primary32_journal.get() && records.source_first_.get()==i.first_lineage.get() &&
         !i.primary32_failed && !i.primary32_pending && i.primary32_source_completed==32 &&
         i.primary32_steps.size()==32 && (!i.frame.primary_dx9_registration_complete||i.installation_has_actual_published_default()) &&
         i.resources.mounts().empty() && (i.default_state->selected.records.empty()||i.installation_has_actual_published_default()),
         "Default projection is not the privately retained SAME parent/source/index operand");
    for(std::size_t n=0;n<b.archives.size();++n) {
        const auto& a=b.archives[n];const auto& step=*i.primary32_steps[n];
        i.require_exact_step_without_callbacks(step);
        need(a.actual_step_brand.get()==step.source_step_brand.get() && a.header.get()==step.header.get() &&
             a.prefix.get()==step.prefix.get() && a.entries.get()==step.entries.get() &&
             a.publication.get()==step.publication.get(),
             "Default projection archive binding differs from actual retained source frame");
    }
}
void BnwNativePackageDiscoveryOwner::validate_default_projection_source(
    const detail::BnwNativePrimary32RecordSourceBindings& b,
    const detail::NativeResourceRecordIndex& records,bool publication_fields_loan)const {
    const auto check=[&]{require_default_projection_operation_current(b,records);};
    check();
    if(b.installation_input){need(!b.lease,"Installed Default projection carries imported save source");
        b.installation_input->require_current();check();b.cold->require_same_input(*b.installation_input);check();
    }else{b.lease->require_current();check();b.cold->require_same_input(*b.lease);check();}
    b.prefixes->require_same_input(*b.cold);check();
    b.initial_policy->require_same_input(*b.cold);check();b.arena->require_same_input(*b.cold);check();
    b.cache->require_same_arena(*b.arena);check();
    if(publication_fields_loan)b.journal->require_current_for_default_publication(*this);
    else if(b.installation_input&&impl_->record_projection_journal_operand_without_callbacks()>=2)
        (void)impl_->current_installation_completed_primary32_journal(*this,*impl_->active_header_fence);
    else b.journal->require_current();
    check();
    for(std::size_t n=0;n<b.archives.size();++n) {
        const auto& a=b.archives[n];a.header->require_current();check();
        // FULL source validation above; only private immutable links are read
        // until the next source call. No allocation, callback or verdict loan.
        a.header->require_default_projection_request_identity_without_callbacks(*b.cold,n);check();
        a.prefix->require_same_owner(*b.prefixes);check();
        a.prefix->require_header_identity_without_callbacks(*a.header);check();
        a.entries->require_same_arena(*b.arena);check();a.publication->require_current();check();
        a.publication->require_default_projection_payload_identity_without_callbacks(*a.header);check();
    }
    if(b.installation_input){b.installation_input->require_current();check();}else{b.lease->require_current();check();}
    b.arena->require_same_default_projection_nodes(b,records); // callback-free final node/handle bookend.
    check();
}
void BnwNativePackageDiscoveryOwner::validate_owned_installed_default_projection_source(
    const detail::BnwNativePrimary32RecordSourceBindings& b,
    const detail::NativeResourceRecordIndex& records)const {
    const auto& i=*impl_;const auto phase=i.record_projection_journal_operand_without_callbacks();
    if(phase!=2&&phase!=3){validate_default_projection_source(b,records);return;}
    const auto* const operand=i.default_projection_pending?i.default_projection_pending.get():i.prepared_default_projection.get();
    const auto* const fence=i.active_header_fence;const auto* const actual_input=i.installation_input.get();
    const auto& input=*actual_input;
    const auto check=[&]{require_default_projection_operation_current(b,records);
        need(i.record_projection_journal_operand_without_callbacks()==phase&&i.active_header_fence==fence&&
             i.installation_input.get()==actual_input&&
             (i.default_projection_pending?i.default_projection_pending.get():i.prepared_default_projection.get())==operand,
             "Retained Default projection tail changed actual Root operand");};
    check();
    if(b.installation_input){need(!b.lease,"Installed Default projection carries imported save source");
        b.installation_input->require_current();check();b.cold->require_same_input(*b.installation_input);check();
    }else{b.lease->require_current();check();b.cold->require_same_input(*b.lease);check();}
    b.prefixes->require_same_input(*b.cold);check();
    b.initial_policy->require_same_input(*b.cold);check();b.arena->require_same_input(*b.cold);check();
    b.cache->require_same_arena(*b.arena);check();
    (void)i.current_installation_completed_primary32_journal(*this,*fence);
    check();
    // The old Journal helper has returned, including its tag/borrower/strict POST.
    const auto controller=+[](const BnwNativePackageDiscoveryOwner& actual,const Impl::HeaderGuard& actual_fence,
                              const BnwNativeInstallationInputOwner& source){
        const auto& state=*actual.impl_;state.require_active_header_without_callbacks();
        const auto actual_phase=state.record_projection_journal_operand_without_callbacks();
        const auto* current=state.default_projection_pending?state.default_projection_pending.get():state.prepared_default_projection.get();
        need((actual_phase==2||actual_phase==3)&&state.active_header_fence==&actual_fence&&
             state.installation_input.get()==&source&&current&&current->source&&
             !state.record_snapshot_failed&&!state.category_lineage_failed,
             "Retained Default projection tail lost actual source/phase/fence");
        // No Root weak-lock/pin: preserve the original outside-owner error/budget.
        actual.require_default_projection_operation_current(*current->source,current->records);
    };
    check();input.require_current();check(); // Strict PRE, after the previous borrower ended.
    {
        BnwNativeInstallationInputOwner::RetainedPrimary32Validation retained(input,*this,*fence,controller);
        BnwDefaultProjectionTailObservation observation(*this,phase);
        for(std::size_t n=0;n<b.archives.size();++n) {
            const auto& a=b.archives[n];a.header->require_current();check();
            // FULL source validation above; only private immutable links are read
            // until the next source call. No allocation, callback or verdict loan.
            a.header->require_default_projection_request_identity_without_callbacks(*b.cold,n);check();
            a.prefix->require_same_owner(*b.prefixes);check();
            a.prefix->require_header_identity_without_callbacks(*a.header);check();
            a.entries->require_same_arena(*b.arena);check();a.publication->require_current();check();
            a.publication->require_default_projection_payload_identity_without_callbacks(*a.header);check();
        }
        if(b.installation_input){b.installation_input->require_current();check();}else{b.lease->require_current();check();}
        b.arena->require_same_default_projection_nodes(b,records); // callback-free final node/handle bookend.
        check();
        retained.require_current();check();
    } // Read-only tag clears BEFORE borrower cleanup on success/unwind.
    input.require_current();check(); // Strict POST before pending move/prepared continuation.
}
void BnwNativePackageDiscoveryOwner::prepare_native_dx9_default_record_projection()const {
    Impl::HeaderGuard fence(impl_->header_callback_state,impl_->self);
    need(fence.valid(),"Default projection parent lost/reentered/foreign thread");auto& i=*impl_;
    need(!i.default_projection_attempted && !i.prepared_default_projection && i.primary32_journal &&
         !i.primary32_failed && !i.primary32_pending && i.primary32_source_completed==32 &&
         i.primary32_steps.size()==32 && !i.frame.primary_dx9_registration_complete,
         "Default projection requires executed SAME primary32 and unconsumed private production phase");
    i.default_projection_attempted=true; // consume BEFORE allocation/provider callbacks.
    struct Failure{Impl& i;bool done=false;~Failure(){if(!done)i.default_projection_failed=true;}} failure{i};
    struct Active{Impl& i;Active(Impl& v,const Impl::HeaderGuard& f):i(v){i.header_active=true;i.active_header_fence=&f;}
        ~Active(){i.active_header_fence=nullptr;i.header_active=false;}} active{i,fence};
    if(i.installation_input){i.validate_installation_primary32_active_source_current();}else{i.validate(true);}i.require_active_header_without_callbacks();
    i.default_projection_brand=std::make_shared<const std::uint8_t>(0);
    i.default_projection_pending=std::make_unique<Impl::PreparedDefaultProjection>();
    auto& prepared=*i.default_projection_pending;
    prepared.source=std::unique_ptr<detail::BnwNativePrimary32RecordSourceBindings>(
        new detail::BnwNativePrimary32RecordSourceBindings());
    auto& b=*prepared.source;b.package=i.self;b.actual_snapshot_brand=i.default_projection_brand;
    b.installation_input=i.installation_input;b.lease=i.lease;b.cold=i.cold;b.prefixes=i.prefixes;b.arena=i.entry_arena;
    b.cache=i.archive_cache;b.journal=i.primary32_journal;
    prepared.records.bind_shared_first(i.first_lineage);
    for(std::size_t n=0;n<b.archives.size();++n) {
        const auto& actual=*i.primary32_steps[n];i.require_exact_step_without_callbacks(actual);
        auto& a=b.archives[n];a.header=actual.header;a.prefix=actual.prefix;a.entries=actual.entries;
        a.publication=actual.publication;a.actual_step_brand=actual.source_step_brand;
    }
    i.entry_arena->capture_default_projection_nodes(b,prepared.records,*this);
    if(i.record_projection_journal_operand_without_callbacks()==2)
        validate_owned_installed_default_projection_source(b,prepared.records);
    else validate_default_projection_source(b,prepared.records);
    if(i.installation_input){i.validate_installation_primary32_active_source_current();}else{i.validate(true);}require_default_projection_operation_current(b,prepared.records);
    i.entry_arena->require_same_default_projection_nodes(b,prepared.records);
    // No callbacks/allocations after final source bookend. Only retain a const
    // prepared operand; externally visible DefaultState/table are UNTOUCHED.
    i.prepared_default_projection=std::move(i.default_projection_pending);failure.done=true;
}
void BnwNativePackageDiscoveryOwner::require_prepared_native_dx9_default_record_projection()const {
    Impl::HeaderGuard fence(impl_->header_callback_state,impl_->self);
    need(fence.valid(),"Prepared default projection parent retired/reentered/foreign thread");auto& i=*impl_;
    need(i.prepared_default_projection && !i.default_projection_failed,"Prepared production default projection absent/poisoned");
    struct Active{Impl& i;Active(Impl& v,const Impl::HeaderGuard& f):i(v){i.header_active=true;i.active_header_fence=&f;}
        ~Active(){i.active_header_fence=nullptr;i.header_active=false;}} active{i,fence};
    struct Failure{Impl& i;bool done=false;~Failure(){if(!done)i.default_projection_failed=true;}} failure{i};
    i.validate(true);const auto& p=*i.prepared_default_projection;validate_default_projection_source(*p.source,p.records);
    failure.done=true;
}
