void BnwNativePackageDiscoveryOwner::register_native_dx9_primary_prefix() const {
    refuse_installed_default_rewrite();
    // Run the genuine installed validator before the imported diagnostic fence;
    // it throws its actual source frontier before any registration mutation.
    if(impl_->installation_input)impl_->validate();
    Impl::HeaderGuard fence(impl_->header_callback_state,impl_->self);
    need(fence.valid(),"Native default/FIRST stage lost/reentered/foreign Package facade");
    impl_->validate();
    auto& i = *impl_;
    need(!i.header_attempted, "Native header frontier cannot resume through diagnostic archive registration");
    need(!i.frame.primary_dx9_registration_complete, "Native primary DX9 prefix already executed");
    DefaultRecords records;
    records.bind_shared_first(i.first_lineage);
    std::vector<Stamp> stamps;
    std::vector<std::filesystem::path> absent;
    auto frame = i.frame;
    static constexpr const char* textures[] = {
        "AmericanWashingtonTextures", "ArabiaHarunAl-RashidTextures", "AztecMontezumaTextures",
        "BuildingTextures", "ChineseWuTextures", "CityTextures", "DecalTextures", "EffectTextures",
        "EgyptianRamessesTextures", "EnglandElizabethTextures", "FeatureTextures",
        "FrenchNapoleonTextures", "GermanBismarckTextures", "GreeceAlexanderTextures",
        "HutsBarbarianFortTextures", "ImprovementTextures", "IndianGandhiTextures",
        "IroquoisHiawathaTextures", "JapaneseOdaNobunugaTextures", "LeadersTextures", "MiscTextures",
        "OttomanSuliemanTextures", "PersiaDariusTextures", "RomanCaesarTextures",
        "RussianCatherineTextures", "SiamRamkhamaengTextures", "SonghaiAskiaTextures",
        "StrategicViewTextures", "TerrainTextures", "UITextures", "UnitsTextures", "WonderTextures"};
    for (const auto* name : textures)
        i.register_archive(std::string("Resource/DX9/") + name + ".fpk", 0, records, frame, stamps, absent);
    // Source54CBE4 calls64A540 before Common/loose registration. This requires
    // actual CVarD80DE0 low-res owner and cannot be bypassed successfully.
    frame.next_resource_dependency = "64A540 low-resolution source CVarD80DE0 before Common/default/Skin registration";
    frame.default_indexed_names = records.records.size();
    frame.resource_crc_collisions = records.collisions;
    frame.primary_dx9_registration_complete = true;
    // Validate all temporary source receipts before atomically publishing the
    // new record state into the SAME retained default callback/table object.
    for (const auto& pin : stamps) need(stamp(pin.path) == pin, "Native resource changed before commit");
    auto first=i.first_lineage->prepare_extension(records.first_record_names);
    i.validate();
    need(fence.valid(),"Native default/FIRST stage caught parent retirement/reentry before adoption");
    i.first_lineage->adopt_prepared(first);
    i.default_state->selected = std::move(records);
    i.resource_stamps = std::move(stamps);
    i.absent_archives = std::move(absent);
    i.frame = std::move(frame);
    ++i.registry.revision;
}

