void BnwNativePackageDiscoveryOwner::register_native_dx9_texture_quality_branch(
    std::shared_ptr<const BnwNativeResourceBootSettingsOwner> settings) const {
    Impl::HeaderGuard fence(impl_->header_callback_state,impl_->self);
    need(fence.valid(),"Native texture/FIRST stage lost/reentered/foreign Package facade");
    struct InstalledActive{Impl& i;bool installed;InstalledActive(Impl& value,const Impl::HeaderGuard& guard):i(value),installed(bool(value.installation_input)){
        if(installed){need(i.installation_high_texture_attempted&&!i.installation_high_texture_returned&&i.installation_boot_returned,
            "Installed texture branch has no genuine consumed actual source stage");i.header_active=true;i.active_header_fence=&guard;}}
        ~InstalledActive(){if(installed){i.active_header_fence=nullptr;i.header_active=false;}}} installed_active(*impl_,fence);
    if(impl_->installation_input){impl_->validate_installation_primary32_active_source_current();}else{impl_->validate();}
    need(static_cast<bool>(settings), "Native texture branch requires actual boot settings");
    settings->require_same_resources(*this);
    const auto& boot = settings->current();
    need(impl_->frame.primary_dx9_registration_complete &&
             !impl_->frame.low_resolution_source_branch_complete,
         "Native TextureQuality branch out of source order/already executed");
    need(boot.normal_launch_source_closed && !boot.leader_viewer &&
             boot.effective_texture_quality.has_value(),
         "Native TextureQuality requires actual saved override or adapter/caps owner");
    need(impl_->resources.mounts().empty(), "Native fresh low-source slot not empty");
    if(impl_->installation_input){need(boot.effective_texture_quality&&*boot.effective_texture_quality!=0,
        "Mandatory actual installed low22 archive constructor/cache source before zero TextureQuality branch");}
    auto& i = *impl_;
    auto frame = i.frame;
    auto stamps = i.resource_stamps;
    auto absent = i.absent_archives;
    std::shared_ptr<DefaultState> low;
    if (*boot.effective_texture_quality == 0) {
        // Source64A565/567→822A50(0,0),82A050 sets group/priority0 and enabled.
        // One separate record set is mounted; its22archives use boolean4→mode2.
        low = std::make_shared<DefaultState>();
        low->selected.bind_shared_first(i.first_lineage);
        static constexpr const char* low_textures[] = {
            "AmericanWashingtonTexturesDX9Low", "ArabiaHarunAl-RashidTexturesDX9Low",
            "AztecMontezumaTexturesDX9Low", "ChineseWuTexturesDX9Low", "CityTexturesDX9Low",
            "EgyptianRamessesTexturesDX9Low", "EnglandElizabethTexturesDX9Low",
            "FrenchNapoleonTexturesDX9Low", "GermanBismarckTexturesDX9Low",
            "GreeceAlexanderTexturesDX9Low", "IndianGandhiTexturesDX9Low",
            "IroquoisHiawathaTexturesDX9Low", "JapaneseOdaNobunugaTexturesDX9Low",
            "MiscTexturesDX9Low", "OttomanSuliemanTexturesDX9Low", "PersiaDariusTexturesDX9Low",
            "RomanCaesarTexturesDX9Low", "RussianCatherineTexturesDX9Low", "SiamRamkhamaengTexturesDX9Low",
            "SonghaiAskiaTexturesDX9Low", "TerrainTexturesDX9Low", "UITexturesDX9Low"};
        for (const auto* name : low_textures)
            i.register_archive(std::string("Resource/DX9_LOW/") + name + ".fpk", 2,
                               low->selected, frame, stamps, absent);
        frame.low_resource_mount_present = true;
        frame.low_indexed_names = low->selected.records.size();
    } else {
        // Fresh13C4 is absent. 64A611/619 reaches64A630 without822C50 call.
        frame.high_texture_quality_source_branch = true;
    }
    frame.low_resolution_source_branch_complete = true;
    frame.next_resource_dependency = "54CBE9 Common archives and original default loose scan before Skin loading";
    for (const auto& pin : stamps) need(stamp(pin.path) == pin, "Native texture sources changed before publication");
    auto first=low ? i.first_lineage->prepare_extension(low->selected.first_record_names)
                   : i.first_lineage->prepare_extension(i.first_lineage->names());
    if(i.installation_input){i.validate_installation_primary32_active_source_current();}else{i.validate();} settings->validate_source();
    need(fence.valid(),"Native texture/FIRST stage caught parent retirement/reentry before adoption");
    if (low) {
        i.resources.mount({1, 0, 0,
            [low](const assets::AssetKey& key) { return low->selected.lookup(key); }, true, true, {},
            [low](std::string_view prefix) { return low->selected.keys(prefix); }});
        i.low_state = std::move(low);
    }
    i.first_lineage->adopt_prepared(first);
    i.resource_stamps = std::move(stamps); i.absent_archives = std::move(absent);
    i.settings = std::move(settings); i.frame = std::move(frame);
    ++i.registry.revision;
}

void BnwNativePackageDiscoveryOwner::register_native_common_high_quality_prefix() const {
    refuse_installed_default_rewrite();
    Impl::HeaderGuard fence(impl_->header_callback_state,impl_->self);
    need(fence.valid(),"Native Common/FIRST stage lost/reentered/foreign Package facade");
    auto& i=*impl_;
    need(!i.production_default_published || !i.common_driver_attempted,"Common production attempt already consumed");
    if(i.production_default_published)i.common_driver_attempted=true;
    struct ProductionFailure{Impl& i;bool done=false;~ProductionFailure(){if(i.production_default_published&&!done)i.header_poisoned=true;}} production_failure{i};
    struct CommonActive{Impl& i;bool enabled;CommonActive(Impl& v,const Impl::HeaderGuard& f):i(v),enabled(v.production_default_published){if(enabled){i.header_active=true;i.active_header_fence=&f;}}
        ~CommonActive(){if(enabled){i.active_header_fence=nullptr;i.header_active=false;}}} common_active{i,fence};
    struct CommonCurrentCost final {
        using Clock=std::chrono::steady_clock;
        std::uint64_t calls=0,completed=0;
        Clock::duration elapsed{};
        int exceptions=0;
        bool operation_complete=false;
        CommonCurrentCost()noexcept {
            const int saved_errno=errno;const DWORD saved_error=GetLastError();
            exceptions=std::uncaught_exceptions();
            SetLastError(saved_error);errno=saved_errno;
        }
        struct Sample final {
            CommonCurrentCost& cost;
            Clock::time_point begin{};
            bool complete=false;
            explicit Sample(CommonCurrentCost& value)noexcept:cost(value) {
                const int saved_errno=errno;const DWORD saved_error=GetLastError();
                ++cost.calls;begin=Clock::now();
                SetLastError(saved_error);errno=saved_errno;
            }
            ~Sample()noexcept {
                const int saved_errno=errno;const DWORD saved_error=GetLastError();
                cost.elapsed+=Clock::now()-begin;if(complete)++cost.completed;
                SetLastError(saved_error);errno=saved_errno;
            }
        };
        ~CommonCurrentCost()noexcept {
            const int saved_errno=errno;const DWORD saved_error=GetLastError();
            const auto stamp=std::chrono::duration_cast<std::chrono::milliseconds>(Clock::now().time_since_epoch()).count();
            const auto elapsed_us=std::chrono::duration_cast<std::chrono::microseconds>(elapsed).count();
            std::fprintf(stderr,"[BNW_COMMON_CURRENT] calls=%llu completed=%llu incomplete=%llu inclusive_us=%lld steady_ms=%lld unwind=%d operation_complete=%d\n",
                static_cast<unsigned long long>(calls),static_cast<unsigned long long>(completed),
                static_cast<unsigned long long>(calls-completed),static_cast<long long>(elapsed_us),
                static_cast<long long>(stamp),std::uncaught_exceptions()>exceptions?1:0,operation_complete?1:0);
            std::fflush(stderr);SetLastError(saved_error);errno=saved_errno;
        }
    } common_current_cost;
    i.validate(i.production_default_published);
    if(i.production_default_published)i.require_active_header_without_callbacks();
    need(i.frame.low_resolution_source_branch_complete && i.settings &&
             i.frame.high_texture_quality_source_branch && !i.low_state &&
             !i.frame.common_high_quality_registration_complete,
         "Native Common/default high-quality stage out of source order or requires low-source scan owner");
    const auto& boot=i.production_default_published?i.settings->common_operation_frame(*this):i.settings->current();
    if(i.production_default_published)i.require_active_header_without_callbacks();
    need(boot.normal_launch_source_closed && !boot.leader_viewer &&
             boot.effective_texture_quality && *boot.effective_texture_quality != 0,
         "Native Common/default stage lost current-process normal/high setting");
    auto records = i.default_state->selected;
    auto native_loose = i.default_state->loose_native;
    auto frame = i.frame;
    auto stamps = i.resource_stamps;
    auto absent = i.absent_archives;
    std::vector<LooseWalk> walks;
    const auto code_page = GetACP();
    static constexpr const char* common_archives[] = {
        "Resource/Common/BuildingModels.fpk", "Resource/Common/CityModels.fpk",
        "Resource/Common/EffectData.fpk", "Resource/Common/FeatureModels.fpk",
        "Resource/Common/HutsBarbarianFortModels.fpk", "Resource/Common/ImprovementModels.fpk",
        "Resource/Common/LeaderModels.fpk", "Resource/Common/MiscData.fpk",
        "Resource/Common/SoundData.fpk", "Resource/Common/TempModels.fpk",
        "Resource/Common/TerrainModels.fpk", "Resource/Common/UnitModels.fpk",
        "Resource/Common/WonderModels.fpk"};
    if(i.production_default_published) {
        execute_common13_source(records,frame,absent);
    } else for (const auto* relative : common_archives)
        i.register_archive(relative, 0, records, frame,stamps,absent);
    assets::LooseResourceIndex canonical(i.shared);
    const auto add_loose_diagnostic = [&](const char* relative, unsigned mode, bool filters, bool xml_override) {
        frame.resource_registration_order.push_back(relative);
        ++frame.loose_registration_requests;
        auto walk = loose_walk(i.original.parent_path() / relative, filters);
        for (const auto& entry : walk.entries) {
            if ((entry.attributes & FILE_ATTRIBUTE_DIRECTORY) != 0) continue;
            ++frame.loose_file_registration_requests;
            const auto source = walk.root / entry.relative;
            const auto mapped = i.shared / relative / entry.relative;
            const auto extension = runtime::ascii_lower(assets::path_utf8(entry.relative.extension()));
            const unsigned actual_mode = xml_override && (extension == ".xml" || extension == ".ggxml") ? 2 : mode;
            if (!std::filesystem::exists(source)) {
                const auto error = native_missing_open(source);
                need(error == ERROR_FILE_NOT_FOUND || error == ERROR_PATH_NOT_FOUND,
                     "Native loose unavailable source requires actual read failure owner");
                const auto relative_name = assets::path_utf8(std::filesystem::path(relative) / entry.relative);
                if (records.insert(entry.native_name, UnreadableLoose{source, relative_name, error,
                    {relative_name, entry.native_name, entry.bytes, entry.written, entry.attributes, error}}, actual_mode))
                    ++frame.loose_files_registered;
                continue; // Retained indexed record, NOT a successful payload alias/skip.
            }
            need(std::filesystem::is_regular_file(mapped), "Canonical native loose mirror missing");
            const auto a = stamp(source), b = stamp(mapped);
            const auto original_id = runtime::identify_file(source);
            const auto mapped_id = runtime::identify_file(mapped);
            need(original_id.bytes == mapped_id.bytes && original_id.sha256 == mapped_id.sha256,
                 "Canonical native loose payload differs from original source");
            need(stamp(source) == a && stamp(mapped) == b, "Native loose source changed during registration");
            stamps.push_back(a); stamps.push_back(b);
            canonical.add_file(mapped);
            const auto asset = canonical.find(assets::AssetKey(assets::path_utf8(entry.relative.filename())));
            const auto* handle = std::get_if<assets::AssetHandle>(&asset);
            need(handle != nullptr, "Native loose canonical handle unavailable");
            if (records.insert(entry.native_name, *handle, actual_mode)) ++frame.loose_files_registered;
        }
        walks.push_back(std::move(walk));
    };
    using QueryFolder=detail::BnwNativeDefaultLooseQueryFolder;
    const auto common_current=[&] {
        CommonCurrentCost::Sample sample(common_current_cost);
        need(i.production_default_published&&i.current_default_source&&i.prefixes&&i.stat_service&&i.lease,
             "Default loose native producer requires genuine production Default/Cold/stat/prefix owners");
        i.require_active_header_without_callbacks();
        i.current_default_source->require_current(*this);
        i.settings->common_operation_frame(*this);i.require_active_header_without_callbacks();
        i.cold->require_same_input(*i.lease);i.require_active_header_without_callbacks();
        need(fence.valid()&&(i.self.use_count()-static_cast<long>(i.directory_parent_internal_pin_count()))>1,"Default loose caller lost last external Package");
        sample.complete=true;
    };
    const auto add_loose = [&](QueryFolder::Caller caller) {
        const QueryFolder folder(caller,*i.settings,*this);
        const auto query=folder.original_query();
        const auto mode=folder.native_mode(); //SAME retained normal startup operand, not a caller bool.
        const bool filters=folder.base_filters(),xml_override=folder.xml_override();
        const char* relative=query.c_str();
        common_current();
        frame.resource_registration_order.push_back(query);
        ++frame.loose_registration_requests;
        const auto root=i.original.parent_path()/std::filesystem::path(native_loose_detail::acp_wide(query));
        LooseWalk walk{root,filters,std::filesystem::exists(root),{},GetACP(),true};
        std::map<std::string,std::pair<std::uint32_t,std::u16string>> folder_prefixes;
        auto root_query=query;std::replace(root_query.begin(),root_query.end(),'/','\\');
        if(root_query.empty()||root_query.back()!='\\')root_query+='\\';
        const auto admit_entry=[&](const native_loose_detail::LooseEntry& entry) {
            if ((entry.attributes & FILE_ATTRIBUTE_DIRECTORY) != 0) return;
            ++frame.loose_file_registration_requests;
            const auto source = walk.root / entry.relative;
            const auto mapped = i.shared / relative / entry.relative;
            const auto extension = runtime::ascii_lower(assets::path_utf8(entry.relative.extension()));
            const unsigned actual_mode = xml_override && (extension == ".xml" || extension == ".ggxml") ? 2 : mode;
            const auto slash=entry.raw_relative.find_last_of('\\');
            const auto child=slash==std::string::npos?std::string{}:entry.raw_relative.substr(0,slash);
            const auto prefix=folder_prefixes.find(child);
            need(prefix!=folder_prefixes.end(),"Default loose FindA entry lacks actual folder registration");
            const auto original_relative=std::filesystem::path(native_loose_detail::acp_wide(query+'\\'+entry.raw_relative));
            common_current();const auto stat=i.stat_service->read_original_relative(original_relative);
            common_current();const auto fields=stat->current();
            if(fields.return_value!=0&&!fields.size&&!fields.mtime) {
                // FindA's ANSI spelling may not select a W filename (best-fit
                // conversion). Retain the failed actual CRT read and actual
                // reconstructed-path open failure, never Unicode/Find fields.
                common_current();const auto error=native_missing_open(source);
                need(error==ERROR_FILE_NOT_FOUND||error==ERROR_PATH_NOT_FOUND,
                     "Default unknown Original stat requires genuine missing reconstructed-path open");
                common_current();stat->require_same_service(*i.stat_service);common_current();
                need(stat->current()==fields,"Default failed Original stat changed before unreadable insertion");
                common_current();
                const auto key=DefaultRecords::source_hash(entry.native_name);
                // Actual finite modes0/1/2/4 use the existing deterministic
                // loose/archive predicate, never unchecked stat mtime. Preserve
                // records.insert FIRST/CRC/mode/bucket behavior without a new
                // blanket collision restriction. Mode6/7 remain unsupported.
                const auto relative_name=assets::path_utf8(std::filesystem::path(relative)/entry.relative);
                if(records.insert(entry.native_name,UnreadableLoose{source,relative_name,error,
                    {relative_name,entry.native_name,entry.bytes,entry.written,entry.attributes,error},stat},actual_mode)) {
                    ++frame.loose_files_registered;
                    native_loose.erase(key); // Never retain prior successful words for this selected unknown HIT.
                }
                common_current();need(stat->current()==fields,"Default failed Original stat changed after unreadable insertion");
                common_current();return;
            }
            if(!(fields.return_value==0&&fields.size&&*fields.size>=0&&fields.mtime))
                throw std::runtime_error(std::string("Default loose unchecked Original stat outputs unknown; cannot manufacture native length")+
                    "; relative="+assets::path_utf8(original_relative)+"; absolute="+assets::path_utf8(source)+
                    "; return="+std::to_string(fields.return_value)+"; errno="+std::to_string(fields.error_number)+
                    "; size="+(fields.size?std::to_string(*fields.size):std::string("UNKNOWN"))+
                    "; mtime="+(fields.mtime?std::to_string(*fields.mtime):std::string("UNKNOWN")));
            const auto publish_node=[&] {
                common_current();stat->require_same_service(*i.stat_service);
                need(stat->current()==fields,"Default native stat changed during selected insertion");
                const auto key=DefaultRecords::source_hash(entry.native_name);
                auto node=std::shared_ptr<DefaultLooseNativeNode>(new DefaultLooseNativeNode);
                node->word_.crc=key;node->word_.length=std::uint32_t(*fields.size);node->word_.offset=0;
                node->prefix_index_=prefix->second.first;
                node->word_.packed_prefix=node->prefix_index_<<20; //Only upper12 authenticated here.
                node->original_find_basename_=entry.native_name;
                node->original_folder_query_=child.empty()?root_query:root_query+child+'\\';
                node->registered_prefix_=prefix->second.second;node->original_stat_=stat;
                native_loose.insert_or_assign(key,std::move(node));common_current();
            };
            if (!std::filesystem::exists(source)) {
                const auto error = native_missing_open(source);
                need(error == ERROR_FILE_NOT_FOUND || error == ERROR_PATH_NOT_FOUND,
                     "Native loose unavailable source requires actual read failure owner");
                const auto relative_name = assets::path_utf8(std::filesystem::path(relative) / entry.relative);
                if (records.insert(entry.native_name, UnreadableLoose{source, relative_name, error,
                    {relative_name, entry.native_name, entry.bytes, entry.written, entry.attributes, error}}, actual_mode))
                    {++frame.loose_files_registered;publish_node();}
                return; // Retained indexed record, NOT a successful payload alias/skip.
            }
            need(std::filesystem::is_regular_file(mapped), "Canonical native loose mirror missing");
            const auto a = stamp(source), b = stamp(mapped);
            const auto original_id = runtime::identify_file(source);
            const auto mapped_id = runtime::identify_file(mapped);
            need(original_id.bytes == mapped_id.bytes && original_id.sha256 == mapped_id.sha256,
                 "Canonical native loose payload differs from original source");
            need(stamp(source) == a && stamp(mapped) == b, "Native loose source changed during registration");
            stamps.push_back(a); stamps.push_back(b);
            canonical.add_file(mapped);
            const auto asset = canonical.find(assets::AssetKey(assets::path_utf8(entry.relative.filename())));
            const auto* handle = std::get_if<assets::AssetHandle>(&asset);
            need(handle != nullptr, "Native loose canonical handle unavailable");
            if (records.insert(entry.native_name, *handle, actual_mode)) {
                ++frame.loose_files_registered;publish_node();
            }
        };
        if(walk.exists) {
            need(std::filesystem::is_directory(root),"Default loose native source is not a directory");
            native_loose_detail::NativeEnumeration enumeration;
            native_loose_detail::visit_loose_entries_with_folder(native_loose_detail::acp_path(root),filters,
                enumeration,[&](const std::string& raw,const std::string& name,DWORD attrs,std::uint64_t size,std::uint64_t written){
                    walk.entries.push_back({std::filesystem::path(native_loose_detail::acp_wide(raw)),name,attrs,size,written,raw});
                    admit_entry(walk.entries.back()); //Actual folder prefix -> FindA -> stat -> insertion before recursion.
                },[&](const std::string& child){
                    common_current();
                    const auto original=child.empty()?root_query:root_query+child+'\\';
                    const auto wide=native_loose_detail::acp_wide(original);
                    const std::u16string raw_prefix(wide.begin(),wide.end());
                    //83A720 registers exact original query folder BEFORE FindA;
                    //neither absolute I/O root nor AssetHandle path is authority.
                    const auto index=i.prefixes->register_loose_source_prefix(raw_prefix,common_current);
                    common_current();folder_prefixes.emplace(child,std::make_pair(index,raw_prefix));
                },"*.*");
        }
        common_current();
        walks.push_back(std::move(walk));
    };
    // Actual54CC9E mode4;74E670 normal1 exclusions and xml/ggxml2;
    // then54CCD1 Shared Speech normal1. High13C4 null closes74E7A3.
    // Low13C4 requires a SECOND bit0x10 scan, not claimed here.
    if(i.production_default_published) {
        add_loose(QueryFolder::Caller::overrides);
        add_loose(QueryFolder::Caller::assets);
        add_loose(QueryFolder::Caller::shared_speech);
    } else {
        add_loose_diagnostic("Resource/Overrides",4,false,false);
        add_loose_diagnostic("Assets",1,true,true);
        add_loose_diagnostic("Assets/Sounds/Speech/Shared",1,false,false);
    }
    frame.native_loose_code_page = code_page;
    for (const auto& [name, record] : records.records)
        if (const auto* unavailable = std::get_if<UnreadableLoose>(&record)) {
            need(native_missing_open(unavailable->native_path) == unavailable->error,
                 "Native indexed unreadable source changed before publication");
            frame.indexed_unreadable_loose.push_back(unavailable->receipt);
        }
    std::sort(frame.indexed_unreadable_loose.begin(), frame.indexed_unreadable_loose.end(),
              [](const auto& a, const auto& b) { return a.relative_path < b.relative_path; });
    frame.default_indexed_names = records.records.size();
    frame.resource_crc_collisions = records.collisions;
    frame.common_high_quality_registration_complete = true;
    frame.next_resource_dependency = "54CD3E64C610/656440 then52D590 global Color reset/read and actual Skin loading";
    for (const auto& walk : walks)
        need(loose_walk_matches(walk), "Native loose source changed before publication");
    for (const auto& pin : stamps) need(stamp(pin.path) == pin, "Native resource changed before publication");
    auto first=i.first_lineage->prepare_extension(records.first_record_names);
    i.validate(i.production_default_published); i.settings->validate_source();
    need(GetACP() == code_page, "Native loose code page changed during registration");
    for(const auto& [key,record]:records.records) {
        const auto* unavailable=std::get_if<UnreadableLoose>(&record);
        if(!unavailable||!unavailable->failed_original_stat)continue;
        common_current();unavailable->failed_original_stat->require_same_service(*i.stat_service);common_current();
        const auto failed=unavailable->failed_original_stat->current();common_current();
        need(failed.return_value!=0&&!failed.size&&!failed.mtime&&native_loose.find(key)==native_loose.end(),
             "Staged unknown Default record has fabricated successful native words");
        need(native_missing_open(unavailable->native_path)==unavailable->error,
             "Staged unknown Default reconstructed-path open changed");
        common_current();unavailable->failed_original_stat->require_same_service(*i.stat_service);common_current();
    }
    need(fence.valid(),"Native Common/FIRST stage caught parent retirement/reentry before adoption");
    for(auto& [key,node]:native_loose) {
        const auto entry=records.records.find(key);
        need(entry!=records.records.end(),"Staged Default loose native node lost selected entry");
        node->selected_entry_=&entry->second;
    }
    i.first_lineage->adopt_prepared(first);
    i.default_state->selected = std::move(records);
    i.default_state->loose_native=std::move(native_loose);
    i.resource_stamps = std::move(stamps); i.absent_archives = std::move(absent);
    i.loose_code_page = code_page;
    i.loose_journals = std::move(walks); i.frame = std::move(frame);
    ++i.registry.revision;
    if(i.production_default_published){
        //Actual returned Default/Common operations own this source stage.
        //No category/Skin/Color bank constructor is a prerequisite.
        need(!i.live_resource_query&&!i.category_source_attempted&&!i.global_color_bank,
             "Live resource query source owner issued out of actual startup order");
        i.live_resource_query=std::shared_ptr<detail::BnwNativeGlobalResourceWarmOwner>(
            new detail::BnwNativeGlobalResourceWarmOwner(i.self,i.identity));
    }
    production_failure.done=true;
    common_current_cost.operation_complete=true;
}

