std::map<std::uint32_t,std::string> detail::BnwNativeSharedFirstLineage::prepare_extension(
    const std::map<std::uint32_t,std::string>& projection) const {
    require_current();auto prepared=storage_.names();
    for(const auto& [crc,name]:projection) {
        const auto [actual,inserted]=prepared.try_emplace(crc,name);
        need(inserted || actual->second==name,"Staged FIRST overwrote authentic earlier namespace name");
    }
    BnwSharedFirstNamesStorageDiagnostic::require_extension(storage_.names(),prepared);
    return prepared; // All allocation before parent's final bookends/store.
}
