void detail::BnwNativeCategoryNamespaceLineage::require_current(const BnwNativePackageDiscoveryOwner& expected) const {
    if(owned_warm_) {
        const auto owner=owned_warm_->lock();need(bool(owner),"Owned category namespace lost actual Warm owner");
        {const auto actual=parent_.lock();need(actual&&actual.get()==&expected,
             "Owned category namespace belongs to another actual Parent");}
        owner->require_owned_namespace_lineage_current(*this);first_->require_current();
        owner->require_owned_namespace_lineage_current(*this);return;
    }
    const auto parent=bnw_shared_first_parent_diagnostic(parent_,expected);
    parent->require_category_namespace_lineage_current(*this);
    eligibility_->require_same_resources(*parent);
    first_->require_current();
    parent->require_category_namespace_lineage_current(*this);
}
void BnwNativePackageDiscoveryOwner::require_category_namespace_lineage_current(
    const detail::BnwNativeCategoryNamespaceLineage& source) const {
    const auto& i=*impl_;
    need(i.thread==std::this_thread::get_id() && !i.header_poisoned && !i.category_lineage_failed &&
         i.lease && source.first_.get()==i.first_lineage.get() && source.eligibility_ &&
         !i.self.owner_before(source.parent_) && !source.parent_.owner_before(i.self) &&
         std::any_of(i.category_namespaces.begin(),i.category_namespaces.end(),
             [&](const auto& actual){return actual.get()==&source;}),
         "Native category namespace foreign/retired/unretained actual parent");
    i.first_lineage->require_current();
}
std::shared_ptr<detail::BnwNativeCategoryNamespaceLineage>
BnwNativePackageDiscoveryOwner::claim_category_namespace_lineage(
    std::shared_ptr<const BnwNativePackagePreSkinOwner> eligibility,std::size_t descriptor,unsigned category) const {
    auto& i=*impl_;need(bool(i.category_source),"Category constructor lacks genuine source operation");
    require_category_source_operation_current(*i.category_source);i.validate(true);
    if(category>=2){
        if(descriptor<i.retained_descriptors.size() && i.retained_descriptors[descriptor].category2_pair)
            i.retained_descriptors[descriptor].category2_pair->revoke_unknown_writer();
        throw std::runtime_error("Native category2 Source writer unsupported; constructor read revoked");
    }
    need(eligibility && category<2 && i.lease && i.first_lineage && i.settings &&
         i.frame.common_high_quality_registration_complete && !i.category_lineage_failed,
         "Native category constructor requires actual SAME high/Common predecessor");
    // No caller row/flags/XML is accepted; inspect the genuine retained child.
    need(i.category_source->predecessor_.get()==eligibility.get(),"Category constructor borrowed another predecessor");
    const auto& frame=eligibility->category_operation_frame(*this);
    need(frame.declared_input_validation_complete && descriptor<frame.packages.size() &&
         frame.packages.size()==i.frame.original_descriptor_order.size(),
         "Native category constructor descriptor source incomplete");
    const auto& row=frame.packages[descriptor];
    need(row.descriptor==i.frame.original_descriptor_order[descriptor] && row.declared_inputs_valid &&
         (row.known_flags_mask&0x40)==0x40 && (row.known_flags_value&0x40)==0 &&
         row.category_mask_source_closed && (row.category_mask&(1u<<category)),
         "Native5F693A invalid/category mask source forbids namespace construction");
    const auto& boot=i.settings->current();
    need(boot.normal_launch_source_closed && !boot.leader_viewer && boot.effective_texture_quality &&
         *boot.effective_texture_quality!=0 && !i.low_state,
         "Native category low paired namespace remains required, cannot invent high profile");
    std::size_t preceding=0;
    for(std::size_t n=0;n<descriptor;++n) {
        need(frame.packages[n].descriptor==i.frame.original_descriptor_order[n],
             "Native category constructor original descriptor order changed");
        if(frame.packages[n].declared_inputs_valid && !(frame.packages[n].known_flags_value&0x40)) preceding+=2;
    }
    need(i.category_namespaces.size()==preceding+category,
         "Native category constructor skipped/repeated original category0 then1");
    // Constructor-only transition: the future private CategorySource owner must
    // still execute each namespace's Paks/directory/preference/load stage before
    // moving to the next category and publishing through the EXISTING table.
    need(i.active_header_fence->valid(),"Native category constructor lost/reentered Package facade");
    struct Failure {Impl& i;bool done=false;~Failure(){if(!done)i.category_lineage_failed=true;}} failure{i};
    auto out=std::shared_ptr<detail::BnwNativeCategoryNamespaceLineage>(
        new detail::BnwNativeCategoryNamespaceLineage(i.self,eligibility,i.first_lineage,descriptor,category));
    auto staged=i.category_namespaces;staged.push_back(out);
    (void)eligibility->category_operation_frame(*this);i.settings->validate_source();i.validate(true);
    need(i.active_header_fence->valid(),"Native category constructor caught parent retirement/reentry");
    i.category_namespaces.swap(staged);failure.done=true;return out;
}

