void BnwNativePackageCategorySourceOwner::require_current()const {
    const NativeQueryParentPin retained_parent(*this);const auto& parent=retained_parent.parent;need(bool(parent),"Native category Package expired");
    if(native_record_borrow_active_)parent->require_category_native_query_parent_current(*this);
    require_from_parent_without_callbacks(*parent);
    parent->require_category_source_operation_current(*this);
    lease_->require_current();
    const auto* ctype=std::setlocale(LC_CTYPE,nullptr);
    need(ctype && std::string_view(ctype)=="C","Native category C CRT ASCII matcher/hash locale changed");
    (void)predecessor_->category_operation_frame(*parent);
    archives_->require_category_borrow_current();
    cold_->require_same_input(*lease_);prefixes_->require_same_input(*cold_);
    auto& i=*parent->impl_;
    for(const auto& stage:stages_) {
        need(stage.source && stage.source->parent_.lock().get()==parent.get() &&
             stage.source->first_.get()==i.first_lineage.get() && stage.source->eligibility_.get()==predecessor_.get() &&
             stage.source->descriptor_<i.retained_descriptors.size(),
             "Native category namespace lost SAME descriptor/FIRST identity");
        parent->require_category_namespace_lineage_current(*stage.source);
        if(stage.arena)stage.arena->require_same_input(*cold_);
        if(stage.cache){need(bool(stage.arena),"Category cache lost genuine arena");stage.cache->require_same_arena(*stage.arena);}
        const auto& retained=i.retained_descriptors[stage.source->descriptor_];
        need(stage.retained_root==&retained.manifest.document && stage.retained_bytes==&retained.ui_skin_original_xml,
             "Native category lexical source replaced retained DOM/buffer");
        native_ui_skin_text_detail::require_captured_bytes(*stage.retained_bytes,
            runtime::identify_file(retained.manifest.path));
        std::vector<std::string> actual_exclusions;
        for(unsigned other=0;other<2;++other)if(other!=stage.source->category_)
            for(const auto* selector:{"Directory","MapDirectory"})
                for(const auto& value:native_category_source_detail::category_values(
                    *stage.retained_root,stage.lexical,other,selector))actual_exclusions.push_back(value);
        need(actual_exclusions==stage.directory_exclusions,
             "Category directory provider rows lost SAME retained native input/order");
        for(const auto& walk:stage.walks)need(native_category_directory_detail::matches(walk,
            stage.directory_exclusions,[&]{stage.namespace_channel->require_current();}),
            "Native category ordered filtered directory source changed");
        for(const auto& absent:stage.absent)need(!std::filesystem::exists(absent),"Native category absent archive changed");
        for(const auto& file:stage.loose) {
            const auto original=runtime::identify_file(lease_->game_root()/file.relative);
            const auto canonical=runtime::identify_file(lease_->canonical_payload_root()/file.relative);
            need(original.sha256==file.original_bytes.sha256 && original.bytes==file.original_bytes.bytes &&
                 canonical.sha256==file.canonical_bytes.sha256 && canonical.bytes==file.canonical_bytes.bytes &&
                 archives_->category_original_loose_stat(file.relative)==file.original_stat,
                 "Native category captured original/canonical loose payload/stat changed");
        }
        for(const auto& [crc,archive]:stage.archived_selected) {
            (void)crc;archive.prefix->require_same_owner(*prefixes_);archive.cache->require_current();
            const auto payload=archive.cache->canonical_payload_source();
            need(payload && archive.ordinal<payload->entries().size(),"Category old archive directory ordinal retired");
        }
    }
    lease_->require_current();parent->require_category_source_operation_current(*this);
    if(native_record_borrow_active_)parent->require_category_native_query_parent_current(*this);
}
void BnwNativePackageCategorySourceOwner::require_namespace_channel_current(
    const detail::BnwNativeCategoryNamespaceChannel& channel,bool initializing)const {
    const NativeQueryParentPin retained_parent(*this);const auto& parent=retained_parent.parent;need(bool(parent),"Native category namespace Package expired");
    require_from_parent_without_callbacks(*parent);
    need(channel.owner_.lock().get()==this && channel.cold_.get()==cold_.get() &&
         channel.lease_.get()==lease_.get() && channel.epoch_.get()==epoch_.get() && channel.brand_ &&
         channel.first_.get()==parent->impl_->first_lineage.get() &&
         std::any_of(stages_.begin(),stages_.end(),[&](const Stage& stage){return
             stage.namespace_channel.get()==&channel && stage.source.get()==channel.namespace_.get();}),
         "Native category foreign/unretained namespace channel");
    if(initializing)need(initializing_namespace_==&channel && active_fence_,
        "Native category namespace initialization outside genuine factory phase");
    if(active_fence_)parent->require_category_source_operation_current(*this);
    else need(sealed_,"Native category channel belongs to incomplete stage");
    lease_->require_current();require_from_parent_without_callbacks(*parent);
}
void BnwNativePackageCategorySourceOwner::require_archive_channel_current(const Channel& channel,bool active)const {
    require_namespace_channel_current(*channel.namespace_channel_,false);
    need(channel.owner_.lock().get()==this && channel.epoch_.get()==epoch_.get() &&
         channel.first_.get()==channel.namespace_->first_.get() && channel.cold_.get()==cold_.get() &&
         channel.namespace_.get()==channel.namespace_channel_->namespace_.get() && channel.brand_,
         "Native category archive lost SAME namespace/source brand");
    need(std::any_of(stages_.begin(),stages_.end(),[&](const Stage& stage){return
         std::any_of(stage.attempts.begin(),stage.attempts.end(),[&](const auto& actual){return actual.get()==&channel;});}),
         "Native category archive request is not retained genuine attempt");
    if(active)need(active_request_==&channel && active_fence_,"Category archive request escaped source issuance phase");
}
