BnwNativeGlobalColorRegistryBank::Scope::~Scope(){bank->busy_.store(false);}
void BnwNativeGlobalColorRegistryBank::require_current(
    const content::XmlNode* document,std::uint64_t occurrence)const {
    need(thread_==std::this_thread::get_id(),"Global Color foreign thread");
    need(!closed_.load(),"Global Color bank retired");
    try {
    if(owned_source_){
        //A read outside an existing genuine Bank operation takes its own Scope.
        //Source callbacks borrow that SAME Scope; each Parent pin is accounted.
        std::unique_ptr<Scope> own_scope;
        if(!busy_.load())own_scope=std::make_unique<Scope>(const_cast<BnwNativeGlobalColorRegistryBank*>(this)->shared_from_this());
        PackagePin held(*this);const auto& parent=held.parent;
        require_owned_current(document,occurrence);
    if(operation_) {
        const auto serial=operation_->operation_serial();
        const auto selected=selected_.lock();const auto window=window_.lock();
        need(selected&&window&&selected.use_count()>1&&window.use_count()>1,
             "Global Color Rules/actual window owner lost");
        selected->require_same_early_package(*parent);
        parent->require_same_selected_host(*selected);
        need(operation_->world_lease().get()==rules_world_.get()&&
             selected->session().read_state_lease().get()==rules_world_.get(),
             "Global Color authentic Rules/world source substituted");
        need(window->native_window()==parent->impl_->lease->actual_hwnd()&&
             window->occurrence()==window_occurrence_&&window->current_extent().has_value(),
             "Global Color genuine native HWND/occurrence retired");
        const auto rules=BnwNativeUiColorOwner::create_from_adopted_host(selected);
        need(rules->global_colors()==rules_rows_,"Global Color authentic selected Rules cache changed");
        operation_->require_operation(serial);
        need(!closed_.load()&&selected.use_count()>1&&window.use_count()>1,
             "Global Color Rules/window lost during callback");
    }
        require_owned_current(document,occurrence);return;
    }
    const auto parent=parent_.lock();
    need(parent&&(parent.use_count()-static_cast<long>(parent->impl_->directory_parent_internal_pin_count()))>1+internal_package_pins_,"Global Color actual Package owner lost");
    parent->require_global_color_bank_current(*this,document,occurrence);
    need(!closed_.load()&&(parent.use_count()-static_cast<long>(parent->impl_->directory_parent_internal_pin_count()))>1+internal_package_pins_,"Global Color Package lost during callback");
    if(operation_) {
        const auto serial=operation_->operation_serial();
        const auto selected=selected_.lock();const auto window=window_.lock();
        need(selected&&window&&selected.use_count()>1&&window.use_count()>1,
             "Global Color Rules/actual window owner lost");
        selected->require_same_early_package(*parent);
        parent->require_same_selected_host(*selected);
        need(operation_->world_lease().get()==rules_world_.get()&&
             selected->session().read_state_lease().get()==rules_world_.get(),
             "Global Color authentic Rules/world source substituted");
        need(window->native_window()==parent->impl_->lease->actual_hwnd()&&
             window->occurrence()==window_occurrence_&&window->current_extent().has_value(),
             "Global Color genuine native HWND/occurrence retired");
        const auto rules=BnwNativeUiColorOwner::create_from_adopted_host(selected);
        need(rules->global_colors()==rules_rows_,"Global Color authentic selected Rules cache changed");
        operation_->require_operation(serial);
        need(!closed_.load()&&selected.use_count()>1&&window.use_count()>1,
             "Global Color Rules/window lost during callback");
    }
    }catch(...){const_cast<BnwNativeGlobalColorRegistryBank*>(this)->poison();throw;}
}
void BnwNativeGlobalColorRegistryBank::initialize_field(
    const std::shared_ptr<BnwNativeColorSlotStorage>& field) {
    need(field&&!field->sets_,"Global Color constructor field replay");
    const std::weak_ptr<BnwNativeGlobalColorRegistryBank> weak=shared_from_this();
    field->sets_.reset(new BnwNativeColorSet64Storage([weak](const content::XmlNode* doc,std::uint64_t occurrence){
        const auto bank=weak.lock();need(bool(bank),"ColorSet actual shared bank owner lost");
        bank->require_current(doc,occurrence);
    }));
}
void BnwNativeGlobalColorRegistryBank::load_base(std::shared_ptr<const content::XmlNode> document) {
    Scope scope(shared_from_this());
    try {
        require_current();need(phase_==Phase::cold&&sources_.empty()&&document,
                              "Global Color cold reset/base source replay");
        // Fresh private construction is the actual cold52D590/4D96C0 reset.
        // No warm reset of somebody else's bank or fabricated empty grant.
        need(global_->colors_.empty()&&roster_.empty(),"Global Color cold reset retained foreign entries");
        sources_.push_back({std::move(document),1,false});
        initialize_field(global_);phase_=Phase::base_colors;
        const auto actual=sources_.front().document;
        //601CA0 FString attribute buffers survive each Color iteration. Refuse
        //missing/duplicate attributes instead of guessing the inherited text.
        for(const auto& node:actual->children)if(node.name=="Color") {
            const std::string* name=nullptr;const std::string* text=nullptr;
            std::set<std::string> attributes;
            for(const auto& [key,value]:node.attributes) {
                need(attributes.insert(key).second,"Global Color duplicate attribute conversion unsupported");
                if(key=="Name")name=&value;if(key=="Color")text=&value;
            }
            need(name&&text,"Global Color native retained attribute buffer source unavailable");
            for(const auto* value:{name,text})for(unsigned char c:*value)
                need(c>=0x20&&c<=0x7e,"Global Color FString conversion unsupported");
            const auto key=native_color_load_detail::hash_query(*name); //601CA0 strlen key.
            if(global_->colors_.contains(key))continue; //First actual hash wins.
            BnwNativeColorSlotStorage::Value value;
            if(!native_color_load_detail::trim(*text).empty()) {
                native_color_load_detail::numeric(*text,value.bits);value.known.fill(true);
            } // Empty numeric input retains unknown allocator bytes, not zeroRGBA.
            require_current(actual.get(),1);
            global_->colors_.emplace(key,value);
        }
        sources_.front().colors_loaded=true;phase_=Phase::base_sets;
        global_->sets_->read_from_same_xml(actual,1,[this](std::uint32_t key){return normal_lookup_for_base(key);});
        require_current(actual.get(),1);phase_=Phase::base_loaded;
    }catch(...){poison();throw;}
}
void BnwNativeGlobalColorRegistryBank::bind_same_roster(
    const std::vector<std::shared_ptr<const BnwNativeUiSkinPoststageInstance>>& actual) {
    Scope scope(shared_from_this());
    try {
        require_current();need(phase_==Phase::base_loaded&&roster_.empty(),"Global Color roster replay/out of order");
        const auto parent=parent_.lock();need(bool(parent),"Global Color roster Package lost");
        for(const auto& instance:actual) {
            need(instance&&instance->query_&&instance->query_->epoch_.get()==epoch_.get()&&
                 !instance->query_->parent_.owner_before(parent_)&&!parent_.owner_before(instance->query_->parent_),
                 "Global Color roster contains foreign source occurrence");
            for(unsigned slot=0;slot!=2;++slot) {
                need(!instance->color_storage_[slot]&&instance->enabled_[slot]==0,
                     "Global Color source constructor field replay/enable fabricated");
                auto field=std::shared_ptr<BnwNativeColorSlotStorage>(new BnwNativeColorSlotStorage);
                initialize_field(field);instance->color_storage_[slot]=std::move(field);
            }
            roster_.emplace_back(instance); //SAME 48C800/798CE0 order, no copied Skin map.
        }
        require_current();phase_=Phase::roster_bound;
    }catch(...){poison();throw;}
}

void BnwNativeGlobalColorRegistryBank::require_skin_query_current(
    const content::XmlNode* source,std::uint64_t occurrence,std::uint32_t slot)const {
    //A distinct SOURCE-token callback; not the Color XML occurrence callback.
    require_current();
    if(!source&&occurrence==0&&slot==2)return;
    need(source&&occurrence>0&&occurrence<=roster_.size()&&slot<2&&
         busy_.load(),
         "Skin manager outside genuine current source scheduler/slot");
    const auto instance=roster_[occurrence-1].lock();
    need(instance&&instance->query_&&instance->query_->node_==source&&
         instance->availability_[slot]&&
         instance->color_storage_[slot],"Skin manager foreign/retired query SOURCE occurrence");
    //require_current's Package check reconstructs descriptor/ordinal/channel,
    //source lease, actual query node, SAME published roster order and HWND.
    //No Style XML, catalog entry or component field can issue that provenance.
    require_current();
}
BnwNativeGlobalColorRegistryBank::ResourceManager
BnwNativeGlobalColorRegistryBank::ensure_slot_resource_manager(std::size_t index,unsigned slot) {
    Scope scope(shared_from_this());
    try {
        require_current();
        need(phase_==Phase::roster_bound&&index<roster_.size()&&slot<2,
             "Skin lazy manager requires genuine issued roster/slot");
        const auto instance=roster_[index].lock();
        need(instance&&instance->query_&&instance->availability_[slot]&&instance->enabled_[slot]==0,
             "Skin unavailable or already-enabled slot cannot start this prefix");
        const auto field=instance->color_storage_[slot];need(bool(field),"Skin constructor storage absent");
        const auto occurrence=std::uint64_t(index)+1;
        //Alias ONLY the genuine private query lease. Its source node is used
        //as identity; Package lifetime/currentness is checked before any access.
        //This does not turn a descriptor node into a loaded Style document.
        const auto source=std::shared_ptr<const content::XmlNode>(instance->query_,instance->query_->node_);
        require_skin_query_current(source.get(),occurrence,slot);
        need(bool(resource_catalog_),"Skin lazy manager lost early Package registry");
        ResourceManager manager;
        if(field->resource_manager8c_) {
            manager=std::static_pointer_cast<BnwNativeSkinDocumentRegistration::Document>(field->resource_manager8c_);
        } else {
            //Exact zero-root constructor+automatic822B50 append, BEFORE Style
            //read. No supplied readiness, mount, namespace or loaded DOM.
            manager=resource_catalog_->retain_resource_manager_from_same_skin_source(source,occurrence,slot);
            require_skin_query_current(source.get(),occurrence,slot);
            field->resource_manager8c_=manager;
        }
        need(manager&&manager->root.get()==source.get()&&manager->source_occurrence==occurrence&&
             manager->slot==slot&&manager->owner.lock().get()==resource_catalog_->state_.get(),
             "Skin lazy getter recovered foreign manager/slot/cache identity");
        require_skin_query_current(source.get(),occurrence,slot);
        return manager;
    }catch(...){poison();throw;}
}

BnwNativeGlobalColorRegistryBank::PackagePin::PackagePin(const BnwNativeGlobalColorRegistryBank& value):bank(value) {
    need(bank.thread_==std::this_thread::get_id()&&bank.busy_.load(),"Skin Package pin outside current owned operation");
    parent=bank.parent_.lock();
    const auto warm=bank.owned_source_?bank.live_resource_query_.lock():nullptr;
    const auto extra=warm?warm->parent_pins_+(parent?parent->impl_->header_callback_state.internal_owner_pin_count():0u):0;
    need(parent&&(parent.use_count()-static_cast<long>(parent->impl_->directory_parent_internal_pin_count()))>1+bank.internal_package_pins_+extra,"Skin private transient pins cannot retain retired outside Package");
    ++bank.internal_package_pins_;
}
BnwNativeGlobalColorRegistryBank::PackagePin::~PackagePin(){--bank.internal_package_pins_;}
namespace skin_resource_scheduler_detail {
std::string c_string(std::string text) {
    text.resize(text.find('\0')==std::string::npos?text.size():text.find('\0'));
    need(std::all_of(text.begin(),text.end(),[](unsigned char c){return c<128;}),
         "Skin native ACP/FString path conversion outside closed ASCII scope");return text;
}
std::string slash(std::string text){text=c_string(std::move(text));std::replace(text.begin(),text.end(),'/','\\');return text;}
std::string directory(std::string text){text=slash(std::move(text));if(text.empty()||text.back()!='\\')text+='\\';return text;}
std::string prefix(const std::string& text){const auto at=text.find_last_of('\\');return at==std::string::npos?"":text.substr(0,at+1);}
std::string basename(const std::string& text){const auto at=text.find_last_of('\\');return at==std::string::npos?text:text.substr(at+1);}
std::filesystem::path physical(const std::filesystem::path& root,const std::string& relative) {
    need(relative.find(':')==std::string::npos&&!relative.empty()&&relative.front()!='\\',
         "Skin drive/absolute/empty native namespace requires its genuine path source owner");
    std::string portable=relative;std::replace(portable.begin(),portable.end(),'\\','/');
    return native_category_source_detail::source_path(root,std::filesystem::path(portable));
}
std::uint64_t mtime(const std::filesystem::path& path) {
    struct __stat64 observed{};
    need(::_stat64(path.string().c_str(),&observed)==0&&observed.st_mtime>=0,
         "Skin actual loose/archive original stat unknown");return std::uint64_t(observed.st_mtime);
}
}
