            // Creator and CURRENT canonical get/control precede saved-source
            // dereferences. Weak witnesses add no hidden outside facade pin.
            need(i.thread==std::this_thread::get_id()&&!i.header_poisoned&&!i.category_lineage_failed,
                 "Retained row validation foreign/poisoned creator");
