        const auto node=i.default_state->loose_native.find(native->crc);
        need(node!=i.default_state->loose_native.end()&&node->second&&&node->second->word_==native,
             "Descriptor loose stream lacks actual selected native insertion witness");
        const auto& actual=*node->second;actual.original_stat_->require_same_service(*i.stat_service);
        const auto& fields=actual.original_stat_->current();
        need(fields.return_value==0&&fields.size&&*fields.size>=0&&std::uint32_t(*fields.size)==native->length,
             "Descriptor loose selected Original stat/extent changed");
