void detail::BnwNativeGlobalResourceWarmOwner::drive_owned_common_gameplay_categories() {
    require_current();need(configured_activation_policy_returned_&&!common_gameplay_driver_returned_&&
        owned_activation_receipts_.size()==returned_standalone_packages_.size(),"Configured category driver replay/source mismatch");
    try{
        //Explicit Civis selected-save policy: Common in actual factory order,
        //then selected GUID Gameplay in that same order. Original startup
        //ordering beyond captured543500/6CD160 is not claimed by this caller.
        for(std::uint32_t category=0;category<2;++category)
            for(std::size_t ordinal=0;ordinal<returned_standalone_packages_.size();++ordinal){
                const auto row=owned_activation_receipts_[ordinal];const auto package=returned_standalone_packages_[ordinal];
                need(row&&row->ordinal==ordinal&&row->package.lock().get()==package.get(),"Configured actual factory receipt reordered");
                if(category==1&&!row->selected_gameplay)continue;
                if(row->effects_returned[category])continue; //Actual first-prefix return may already exist.
                const auto before=owned_category_stages_.size();prepare_owned_category_manager(ordinal,category);
                if(owned_category_stages_.size()==before){
                    need(row->effects_returned[category],"Native flags-gated dispatch did not return its real zero branch");continue;
                }
                need(owned_category_stages_.size()==before+1,"Category dispatch did not retain exactly one actual namespace");
                const auto stage=owned_category_stages_.back();resume_owned_category_paks_effects(stage);resume_owned_category_final_effects(stage);
                require_current();
            }
        for(const auto& row:owned_activation_receipts_){
            need(row&&row->effects_returned[0]&&(!row->selected_gameplay||row->effects_returned[1]),
                "Common/selected Gameplay real effect journal incomplete");
            const auto package=row->package.lock();need(bool(package),"Configured terminal factory package retired");
            package->with_actual_descriptor([&](const auto& loan){loan.require_current();
                need(&loan.document()==row->document&&loan.fields().current_category_mask()==row->expected_mask,
                    "Configured effect journal lost SAME current Core state");loan.require_current();});
        }
        need(std::all_of(owned_category_stages_.begin(),owned_category_stages_.end(),[](const auto& stage){
            return stage&&stage->step==OwnedCategoryStage::Step::name_registered;}),"Configured actual namespace operations still pending");
        require_current();common_gameplay_driver_returned_=true;
        //UISkin constructor/selection/effects and Bank are separate genuine
        //operations. This return cannot issue their completion or full seal.
    }catch(...){failed_.store(true);throw;}
}
