    //weak; no copied frame or replacement input participates in this receipt.
    const std::shared_ptr<const BnwNativeResourceBootSettingsOwner> settings_;
    const std::shared_ptr<const runtime::BnwSelectedLanguageInputOwner> selected_input_;
    const assets::ResourceMountTable* const actual_table_;
