                                need(default_header&&publication&&&archive_prefix->header_owner_completed(completed,cold,*i.prefixes)==default_header.get()&&
                                     publication->canonical_payload_source_completed(completed,cold,*i.entry_arena,*i.prefixes,*i.archive_cache).get()==native.source.get(),
                                     "Completed Default archive lost SAME publication/header/source");
