void detail::BnwNativeGlobalResourceWarmOwner::require_returned_standalone_package_loaded_current_completed(
    const BnwNativeStandalonePackageLoaded& token,const BnwNativeCompletedColdSourceLoan& loan,
    const BnwNativeColdFilesystemOwner& cold)const {
    require_current_completed(loan,cold);ParentPin retained(*this);
    const auto issued=std::find_if(returned_standalone_packages_.begin(),returned_standalone_packages_.end(),
        [&](const auto& value){return value&&value.get()==&token&&!value.owner_before(token.self_)&&!token.self_.owner_before(value);});
    need(issued!=returned_standalone_packages_.end(),"Completed Loaded has no actual returned factory/control membership");
    const auto actor=std::find_if(preload_receivers_.begin(),preload_receivers_.end(),[&](const auto& receiver){
        return receiver&&!receiver.owner_before(token.actor_)&&!token.actor_.owner_before(receiver)&&
            receiver->state_->receiver.get()==token.actual_receiver_&&
            receiver->state_->completed_metadata_identity==token.actual_metadata_&&
            !receiver->state_->returned_loaded.owner_before(*issued)&&!issued->owner_before(receiver->state_->returned_loaded);
    });
    need(actor!=preload_receivers_.end()&&(*actor)->state_->thread==thread_&&!(*actor)->state_->closed.load(),
         "Completed returned factory lost its actual retained receiver/metadata storage");
    //Do not call token.check or actor.current_completed here: either calls
    //this exact factory-membership gate. Their own explicit suppliers perform
    //filename/parser/metadata validation under the same real source loan.
    retained.parent->require_native_owned_completed_warm_source_current(*this,loan,cold);
    require_current_completed(loan,cold);
}

void detail::BnwNativeGlobalResourceWarmOwner::require_same_selected_language_input_completed(
    const runtime::BnwSelectedLanguageInputOwner& actual,const BnwNativeCompletedColdSourceLoan& loan,
    const BnwNativeColdFilesystemOwner& cold)const {
    require_current_completed(loan,cold);ParentPin retained(*this);const auto& i=*retained.parent->impl_;
    const auto finalization=owned_skin_bank_finalization_return_;
    need(finalization&&finalization->policy&&finalization->policy==owned_skin_boot_policy_&&i.settings&&
         finalization->policy->boot_.lock().get()==i.settings.get(),
         "Completed selected input lacks SAME retained actual Boot/finalizer policy");
    const auto input=finalization->policy->input_.lock();
    need(input&&input.get()==&actual,"Completed selected language is not the genuine captured Boot input");
    //Actual Core completed checker still validates RuntimeInput/CRT through
    //its SAME Boot branch. This relation must not call old input.current.
    retained.parent->require_native_owned_completed_warm_source_current(*this,loan,cold);
    require_current_completed(loan,cold);
}

void detail::BnwNativeGlobalResourceWarmOwner::require_owned_namespace_channel_current_completed(
    const BnwNativeCategoryNamespaceChannel& channel,const BnwNativeCompletedColdSourceLoan& loan,
    const BnwNativeColdFilesystemOwner& cold)const {
    require_current_completed(loan,cold);ParentPin retained(*this);const auto& i=*retained.parent->impl_;
    const auto found=std::find_if(owned_category_stages_.begin(),owned_category_stages_.end(),
        [&](const auto& stage){return stage&&stage->namespace_channel.get()==&channel;});
    need(found!=owned_category_stages_.end(),"Completed Namespace is not the SAME retained executed Stage");
    const auto stage=*found;const auto package=stage->package.lock();const auto manager=stage->manager.lock();
    need(stage->step==OwnedCategoryStage::Step::name_registered&&stage->category<3&&!stage->active_request&&
         stage->source&&stage->arena&&stage->cache&&stage->selected_source&&stage->document&&
         package&&stage->factory_ordinal<returned_standalone_packages_.size()&&
         returned_standalone_packages_[stage->factory_ordinal]==package&&manager&&manager->current89&&
         manager->source_kind==BnwNativeSkinDocumentRegistration::SourceKind::owned_package&&
         channel.owned_warm_&&!channel.owned_warm_->owner_before(i.live_resource_query)&&
         !i.live_resource_query.owner_before(*channel.owned_warm_)&&channel.arena_claimed_&&channel.brand_&&
         channel.namespace_.get()==stage->source.get()&&channel.cold_.get()==&cold&&
         channel.lease_.get()==i.lease.get()&&channel.first_.get()==i.first_lineage.get()&&
         channel.epoch_.get()==epoch_.get()&&stage->source->owned_warm_&&
         stage->source->descriptor_==stage->factory_ordinal&&stage->source->category_==stage->category&&
         !stage->source->owned_package_.owner_before(package)&&!package.owner_before(stage->source->owned_package_),
         "Completed Namespace lost actual terminal Stage/factory/manager/FIRST/Cold identity");
    if(stage->category==2){
        const auto instance=stage->skin_instance.lock();const auto occurrence=stage->skin_occurrence.lock();
        need(instance&&occurrence&&stage->skin_slot<2&&stage->skin_member==0&&
             occurrence->roster_index_<owned_skin_instances_.size()&&owned_skin_instances_[occurrence->roster_index_]==instance&&
             occurrence->roster_index_<owned_skin_occurrences_.size()&&owned_skin_occurrences_[occurrence->roster_index_]==occurrence&&
             occurrence->package_.lock()==package&&occurrence->document_==stage->document&&
             instance->owned_resource_pairs_[stage->skin_slot][stage->skin_member]==manager,
             "Completed Namespace differs from actual constructed Skin occurrence/pair");
    }
    //Only retained identity/index authority is lent here. No old Loaded,
    //Arena, Cache or Common validator is called recursively; their completed
    //validators must replay the real rows/files in their explicit domain.
    retained.parent->require_native_owned_completed_warm_source_current(*this,loan,cold);
    require_current_completed(loan,cold);
}

