void detail::BnwNativeGlobalResourceWarmOwner::replay_owned_category_stage_io_current_completed(
    const OwnedCategoryStage& stage,const BnwNativeCompletedColdSourceLoan& loan,const BnwNativeColdFilesystemOwner& cold)const {
    need(thread_==std::this_thread::get_id(),"Owned Stage IO replay foreign creator thread");
    ParentPin retained(*this);const auto& i=*retained.parent->impl_;
    require_current_completed(loan,cold);
    const auto& epoch=retained.parent->lend_native_owned_completed_loose_source_epoch(*this,loan,cold);
    const auto check=[&]{require_current_completed(loan,cold);require_owned_completed_category_stage_fence_without_callbacks(stage);
        need(&retained.parent->lend_native_owned_completed_loose_source_epoch(*this,loan,cold)==&epoch,
             "Completed Stage Find replay lost actual Epoch identity");};
    check();
    if(stage.loose_source)stage.loose_source->with_current_completed(loan,cold,[&]{
      for(const auto& receipt:stage.find_receipts){
        const auto relative=stage.loose_source->relative_path_completed(receipt.query);const auto parent=relative.parent_path();
        const auto parent_io=parent.empty()?epoch.game_root():native_category_source_detail::source_path(epoch.game_root(),parent);
        check();const auto io=native_loose_detail::acp_path(parent_io/relative.filename());
        std::vector<OwnedCategoryStage::FindEvent> events;DWORD error=0;
        native_loose_detail::NativeEnumeration enumeration;auto cursor=enumeration.open(io);
        if(!cursor.valid())error=cursor.error();
        else{
            do{const auto& event=cursor.data;events.push_back({event.cFileName,event.dwFileAttributes,
                (std::uint64_t(event.nFileSizeHigh)<<32)|event.nFileSizeLow,
                (std::uint64_t(event.ftLastWriteTime.dwHighDateTime)<<32)|event.ftLastWriteTime.dwLowDateTime});
            }while(cursor.next());error=cursor.error();
        }
        need(events==receipt.events&&error==receipt.end_error,"Owned actual Directory/File FindA sequence changed");
    }
    });check();
    for(const auto& absent:stage.absent){
        check();
        need(GetFileAttributesA(native_loose_detail::acp_path(absent).c_str())==INVALID_FILE_ATTRIBUTES,
             "Owned previously absent archive appeared in current source universe");
        const auto error=GetLastError();need(error==ERROR_FILE_NOT_FOUND||error==ERROR_PATH_NOT_FOUND,
             "Owned absent archive now has unknown Original IO failure");
    }check();
}
